CREATE VIEW substance_cards AS
            SELECT s.id AS substance_id, coalesce(v.overrides,'{}'::jsonb) AS overrides,
                coalesce(v.sources,'{}'::jsonb) AS sources, coalesce(v.checks,'{}'::jsonb) AS checks
            FROM substances s LEFT JOIN substance_properties p ON p.substance_id=s.id
            LEFT JOIN LATERAL (
                SELECT jsonb_object_agg(a.field_key, coalesce(to_jsonb(a.qualifier), CASE a.field_key WHEN 'name' THEN to_jsonb(p."name") WHEN 'formula' THEN to_jsonb(p."formula") WHEN 'formulaAlt' THEN to_jsonb(p."formula_alt") WHEN 'cas' THEN to_jsonb(p."cas") WHEN 'icsc' THEN to_jsonb(p."icsc") WHEN 'intlName' THEN to_jsonb(p."intl_name") WHEN 'intlSyn' THEN to_jsonb(p."intl_syn") WHEN 'note' THEN to_jsonb(p."note") WHEN 'comment' THEN to_jsonb(p."comment") WHEN 'phaseNu' THEN to_jsonb(p."phase_nu") WHEN 'grpRF' THEN to_jsonb(p."grp_r_f") WHEN 'hazClass' THEN to_jsonb(p."haz_class") WHEN 'hazSanpin' THEN to_jsonb(p."haz_sanpin") WHEN 'api581cls' THEN to_jsonb(p."api581cls") WHEN 'repEnv' THEN to_jsonb(p."rep_env") WHEN 'repMethod' THEN to_jsonb(p."rep_method") WHEN 'nfpaS' THEN to_jsonb(p."nfpa_s") WHEN 'mw' THEN to_jsonb(p."mw") WHEN 'mw_icsc' THEN to_jsonb(p."mw_icsc") WHEN 'mw_cameo' THEN to_jsonb(p."mw_cameo") WHEN 'mw_kor' THEN to_jsonb(p."mw_kor") WHEN 'mw_nfpa' THEN to_jsonb(p."mw_nfpa") WHEN 'nbp' THEN to_jsonb(p."nbp") WHEN 'nbp_icsc' THEN to_jsonb(p."nbp_icsc") WHEN 'nbp_cameo' THEN to_jsonb(p."nbp_cameo") WHEN 'nbp_kor' THEN to_jsonb(p."nbp_kor") WHEN 'nbp_nfpa' THEN to_jsonb(p."nbp_nfpa") WHEN 'ait' THEN to_jsonb(p."ait") WHEN 'ait_icsc' THEN to_jsonb(p."ait_icsc") WHEN 'ait_cameo' THEN to_jsonb(p."ait_cameo") WHEN 'ait_kor' THEN to_jsonb(p."ait_kor") WHEN 'ait_nfpa' THEN to_jsonb(p."ait_nfpa") WHEN 'dens' THEN to_jsonb(p."dens") WHEN 'dens_icsc' THEN to_jsonb(p."dens_icsc") WHEN 'dens_cameo' THEN to_jsonb(p."dens_cameo") WHEN 'dens_kor' THEN to_jsonb(p."dens_kor") WHEN 'dens_nfpa' THEN to_jsonb(p."dens_nfpa") WHEN 'idlh' THEN to_jsonb(p."idlh") WHEN 'idlh_icsc' THEN to_jsonb(p."idlh_icsc") WHEN 'idlh_cameo' THEN to_jsonb(p."idlh_cameo") WHEN 'idlh_kor' THEN to_jsonb(p."idlh_kor") WHEN 'idlh_nfpa' THEN to_jsonb(p."idlh_nfpa") WHEN 'pdk' THEN to_jsonb(p."pdk") WHEN 'pdk_icsc' THEN to_jsonb(p."pdk_icsc") WHEN 'pdk_cameo' THEN to_jsonb(p."pdk_cameo") WHEN 'pdk_kor' THEN to_jsonb(p."pdk_kor") WHEN 'pdk_nfpa' THEN to_jsonb(p."pdk_nfpa") WHEN 'flammable' THEN to_jsonb(p."flammable") WHEN 'toxic' THEN to_jsonb(p."toxic") WHEN 'nfnt' THEN to_jsonb(p."nfnt") WHEN 'inert' THEN to_jsonb(p."inert") WHEN 'nfpaH' THEN to_jsonb(p."nfpa_h") WHEN 'nfpaF' THEN to_jsonb(p."nfpa_f") WHEN 'nfpaI' THEN to_jsonb(p."nfpa_i") WHEN 'phaseNu_icsc' THEN to_jsonb(p."phase_nu_icsc") WHEN 'phaseNu_cameo' THEN to_jsonb(p."phase_nu_cameo") WHEN 'phaseNu_kor' THEN to_jsonb(p."phase_nu_kor") WHEN 'mwNote' THEN to_jsonb(p."mw_note") WHEN 'nbpNote' THEN to_jsonb(p."nbp_note") WHEN 'aitNote' THEN to_jsonb(p."ait_note") WHEN 'densNote' THEN to_jsonb(p."dens_note") WHEN 'idlhNote' THEN to_jsonb(p."idlh_note") WHEN 'pdkNote' THEN to_jsonb(p."pdk_note") WHEN 'intlNameNote' THEN to_jsonb(p."intl_name_note") WHEN 'phaseNuNote' THEN to_jsonb(p."phase_nu_note") WHEN 'hazSanpinNote' THEN to_jsonb(p."haz_sanpin_note") WHEN 'hazClassNote' THEN to_jsonb(p."haz_class_note") WHEN 'ref' THEN to_jsonb(p."ref") WHEN 'refIcsc' THEN to_jsonb(p."ref_icsc") WHEN 'refCameo' THEN to_jsonb(p."ref_cameo") WHEN 'refNfpa' THEN to_jsonb(p."ref_nfpa") WHEN 'refKor' THEN to_jsonb(p."ref_kor") WHEN 'refNiosh' THEN to_jsonb(p."ref_niosh") WHEN 'idlhUnit' THEN to_jsonb(p."idlh_unit") ELSE NULL::jsonb END, 'null'::jsonb)) FILTER (WHERE a.value_present) AS overrides,
                    jsonb_object_agg(a.field_key,jsonb_build_object('citation',a.citation,'conditions',a.conditions,'by',a.source_by,
                        'at',(to_jsonb(a.source_at AT TIME ZONE 'UTC')#>>'{}')||'+00:00')) FILTER (WHERE a.source_present) AS sources,
                    jsonb_object_agg(a.field_key,jsonb_build_object('by',a.verified_by,
                        'at',(to_jsonb(a.verified_at AT TIME ZONE 'UTC')#>>'{}')||'+00:00')) FILTER (WHERE a.verified_at IS NOT NULL) AS checks
                FROM substance_property_annotations a WHERE a.substance_id=s.id
            ) v ON true;
